import{_ as t,o as n,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/endpoints.md","filePath":"concepts/endpoints.md","lastUpdated":1784612679000}'),o={name:"concepts/endpoints.md"};function d(i,e,p,r,c,l){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h1><p>An endpoint is a specific HTTP method + path that can be invoked (e.g., <code>GET /api/users/{id}</code>). Endpoints are the actual API operations that the LLM discovers, inspects, and calls.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>Each endpoint contains:</p><ul><li><strong>HTTP method</strong>: GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS</li><li><strong>Path</strong>: <code>/api/v1/users/{id}</code></li><li><strong>Summary</strong>: a short description of what the endpoint does — very useful for the LLM to understand its purpose at a glance</li><li><strong>Description</strong>: a detailed explanation of the endpoint&#39;s behavior, parameters, and use cases</li><li><strong>Parameters</strong>: path, query, header, cookie</li><li><strong>Request body</strong>: for POST/PUT/PATCH</li><li><strong>Responses</strong>: status codes and response schemas</li></ul><p>The <code>summary</code> and <code>description</code> fields come from the OpenAPI/Swagger/Postman file. They are the primary way the LLM understands what an endpoint does. Well-written summaries make endpoint discovery much more effective.</p><h2 id="mcp-tools-for-endpoints" tabindex="-1">MCP Tools for Endpoints <a class="header-anchor" href="#mcp-tools-for-endpoints" aria-label="Permalink to &quot;MCP Tools for Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>All endpoints in a spec</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Endpoints in a collection</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Endpoints in a tag</td></tr><tr><td><code>endpoint_by_id</code></td><td>Quick endpoint summary</td></tr><tr><td><code>inspect</code></td><td>Full endpoint details (schemas, params)</td></tr><tr><td><code>invoke</code></td><td>Call the endpoint</td></tr><tr><td><code>search</code></td><td>Search endpoints by text</td></tr></tbody></table><h2 id="deprecated-endpoints" tabindex="-1">Deprecated Endpoints <a class="header-anchor" href="#deprecated-endpoints" aria-label="Permalink to &quot;Deprecated Endpoints&quot;">​</a></h2><p>Endpoints marked as <code>deprecated</code> in the spec are shown with a notice when inspected.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Endpoints are <strong>read-only</strong> from swag2mcp&#39;s perspective. There are no YAML config settings for endpoints — you cannot add, remove, rename, or modify them in <code>swag2mcp.yaml</code>.</p><p>To change endpoints (add new ones, update summaries, modify parameters, mark as deprecated), edit the original OpenAPI/Swagger/Postman file and run <code>swag2mcp update</code> to re-parse and re-index.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Query: &quot;Show details for GET /pet/{petId}&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ Result:</span></span>
<span class="line"><span>  GET /pet/{petId}</span></span>
<span class="line"><span>  Summary: Find pet by ID</span></span>
<span class="line"><span>  Description: Returns a single pet by its ID</span></span>
<span class="line"><span>  Parameters:</span></span>
<span class="line"><span>    - petId (path, integer, required)</span></span>
<span class="line"><span>  Responses:</span></span>
<span class="line"><span>    - 200: Pet object</span></span>
<span class="line"><span>    - 400: Error</span></span>
<span class="line"><span>    - 404: Not found</span></span></code></pre></div>`,15)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
